document.addEventListener("DOMContentLoaded",function(){var e=document.querySelectorAll(".hw-map-zone");e.forEach(function(t){t.addEventListener("click",function(){!function(t){e.forEach(function(e){e.classList.remove("hw-zone-active"),e.setAttribute("aria-pressed","false")}),t.classList.add("hw-zone-active"),t.setAttribute("aria-pressed","true")}(t)})})});